#!/usr/bin/env python3
from pathlib import Path
import json,statistics,re
base=Path('docs/research/100bit-spend-path-20261013');E=base/'evidence/prover-speed-20261022';P=base/'design/PROVER-SPEED-20261022.md';d=json.loads((E/'summary.json').read_text())
lines=['## Results (measurement)','', '**The under-15-second target is not met.** Twenty primary proofs completed: five transfer and five withdrawal proofs on each pinned variant, all with one attempt, 57,607 bytes and passing strict tx1/tx2 plus dense verification. These fresh-randomness fixture measurements do not bound retry tails or arbitrary witnesses.', '', '| Variant | Fixture | n | Median s | Min–max s | Sample SD s | Attempts |','|---|---|---:|---:|---:|---:|---|']
for mode in d:
 for f,x in d[mode]['fixtures'].items():
  t=x['wall_seconds'];lines.append(f"| {mode} | {f} | {t['n']} | {t['median']:.6f} | {t['min']:.6f}–{t['max']:.6f} | {t['sample_stdev']:.6f} | {x['attempts']} |")
lines+=['','The samples ran research first, then v2, each as five alternating transfer/withdrawal pairs. They were not randomized between variants, cold-cache trials, CPU-pinned trials or a statistical equivalence study. The early warmup/drift and shared-host scheduling remain part of the spread. No v2 sample crossed the D168 +10% gate relative to its fixture’s research median.','', '### Phase medians (seconds; measurement)', '', 'Columns are research transfer / research withdrawal / v2 transfer / v2 withdrawal. Hierarchical rows marked “child” are included in their parent and must not be added again. Very small values retain six decimals so “zero” is not confused with unmeasured.', '', '| Phase | Research T | Research W | V2 T | V2 W |','|---|---:|---:|---:|---:|']
cols=[(m,f) for m in ['research','v2'] for f in ['transfer','withdrawal']]
def series(m,f):return [r for r in d[m]['per_run'] if r['fixture']==f]
def inc(r,k):return r['phases_inclusive_exclusive_calls'][k][0]
def exc(r,k):return r['phases_inclusive_exclusive_calls'][k][1]
phases=[('Entropy (callback; OS nonce + two private seeds)',lambda r:inc(r,'entropy')),('Durable reservation (file + directory fsync)',lambda r:r['reservation_seconds']),('SeedExpander mask material after reservation',lambda r:inc(r,'reservation_and_mask_material')-r['reservation_seconds']),('Profile21 zero-factor D expansion',lambda r:inc(r,'profile21_d')),('Mask apply/audit and residual cleanup',lambda r:exc(r,'mask_apply_audit')),('Private salt derivation, three full arrays',lambda r:inc(r,'salts')),('Encoding-domain construction',lambda r:inc(r,'encoding_domain')),('C1+C2 commitments (parent)',lambda r:inc(r,'commit_c1')+inc(r,'commit_c2')),('↳ 29 lane encodings (child)',lambda r:inc(r,'encoding')),('Semantic build excluding commitments/sumcheck/pole (exclusive)',lambda r:exc(r,'semantic')),('Pole check',lambda r:inc(r,'pole_check')),('Semantic sumcheck (parent)',lambda r:inc(r,'semantic_sumcheck')),('↳ Point claims (child)',lambda r:inc(r,'semantic_point_claims')),('↳ Terminal evaluations (child)',lambda r:inc(r,'semantic_terminal')),('Opening rounds + folds',lambda r:inc(r,'sumcheck_round')+inc(r,'sumcheck_fold')),('Opening weights + materialization',lambda r:inc(r,'weights')+inc(r,'weights_materialize')),('Folded-word encoding',lambda r:inc(r,'folded_encoding')),('C1+C2 leaf assembly/hash (commitment child)',lambda r:inc(r,'commit_leaves')),('Folded leaf assembly/hash',lambda r:inc(r,'folded_leaves')),('All three Merkle parent trees (C1+C2 are commitment children)',lambda r:inc(r,'tree_parents')),('Opening transcript (exclusive; semantic transcript below)',lambda r:exc(r,'transcript')),('P_R1 total (parent)',lambda r:inc(r,'p_r1'))]
for k in ['public_data','emit','convert','build','check']:phases.append(('↳ P_R1 '+k+(' (lane preparation + conversion)' if k=='convert' else '')+' (child)',lambda r,k=k:r['p_r1_split'][k]))
phases += [('Publication: compact bytes + openings/multiproofs',lambda r:inc(r,'publication')),('Opening arithmetic/serialization residual (exclusive)',lambda r:exc(r,'opening_sumcheck_other'))]
for title,fun in phases:
 values=[statistics.median([fun(r) for r in series(m,f)]) for m,f in cols];lines.append('| '+title+' | '+' | '.join(f'{v:.6f}' for v in values)+' |')
lines+=['','The semantic sumcheck made 28,645 terminal calls and 28,646 point-claim calls per proof. `convert` includes `Lanes::new` just before conversion, as in the existing combined builder timer. P_R1 total also includes cleanup/catch/TLS overhead, so its timed children do not sum exactly to the parent. Exclusive timer sums agree with each end-to-end proof time within 1 ms (`summarize.py` checks this). Instrumentation overhead was not separately subtracted; this is a measured scratch binary, not a formal cost model.','', '### Critical-path arithmetic (projection)', '']
for m,f in cols:
 rs=series(m,f);a=statistics.median([inc(r,'p_r1') for r in rs]);b=statistics.median([r['wall_seconds']-inc(r,'p_r1') for r in rs]);needed=a/(15-b)
 lines.append(f'* {m} {f}: P_R1 {a:.3f} s, remainder {b:.3f} s. Even making all non-P_R1 work free leaves {a:.3f} s. Holding the remainder fixed needs **>{needed:.2f}×** P_R1 acceleration to get strictly below 15 s; 4× projects {b+a/4:.3f} s for one attempt.')
lines+=['','All observations used one attempt. For a k-attempt call, rejected work remains part of proof latency. These samples do not establish a rejection-rate distribution or worst-case under-15 bound; an eight-attempt cap is not itself such a bound. No acceptance check, fresh seed or ledger reservation was removed.','', '### Host and resource receipts (measurement)', '', 'Intel Core Ultra 7 155H, x86_64 Linux native, **16 physical cores / 22 logical CPUs** (hybrid topology). Rustc **1.94.1**, LLVM **21.1.8**. Release profile, `-j4`, locked dependency graph, `RUSTFLAGS=-C link-arg=-Wl,--threads=4`; research `optimized-terminal,r1p-check`, v2 `optimized-terminal,ct-host-prover`. Per-package checked overflow stays enabled for the extracted certificate crates. SHA-256 instruction excerpts and source/native binary hashes are retained; instruction presence is not proof of dispatch frequency or L3 constant-time behaviour.','', '| Primary process | Exit | Wall s incl. setup/verification | Peak RSS KiB | Cgroup peak bytes | Swap events | Observed thread counts |','|---|---:|---:|---:|---:|---:|---|']
for mode in ['research','v2']:
 O=E/'receipts'/(mode+'-run');r=json.loads((O/'receipt.json').read_text());t=(O/'time.log').read_text();rss=re.search(r'Maximum resident set size \(kbytes\):\s*(\d+)',t)[1];swap=re.search(r'Swaps:\s*(\d+)',t)[1];threads=sorted(set(x['threads'] for x in r['thread_samples']));lines.append(f"| {mode} | {r['exit']} | {r['wall_seconds']:.3f} | {rss} | {r['memory_peak']} | {swap} | {threads} |")
lines+=['','Each build and run used MemoryHigh=6G, MemoryMax=8G, MemorySwapMax=0, TasksMax=64. Build/run exits, GNU-time RSS, cgroup peaks and swap evidence are under `receipts/`. The initial finite-cap reservation including this job was 32.375 GiB against the 55 GiB limit; subsequent admissions are recorded. The whole route is not single-threaded: see the threading correction below. These are Rust measurements; `#print axioms` is N/A and no Lean job or formal release replay ran.','']
s=P.read_text().replace('## Results\n\nPending.','\n'.join(lines)).replace('## Ranked proposals and security consequences\n\nPending.\n\n','')
P.write_text(s)
